/bin/bash -lc "curl -sS --get 'https://usegalaxy.org/api/tools/toolshed.g2.bx.psu.edu/repos/devteam/samtools_mpileup/samtools_mpileup/2.2.0' --data-urlencode 'io_details=true' -H \"x-api-key: "'$(cat $GALAXY_API_KEY_FILE)" | python3 -c '"'
import sys,json
j=json.load(sys.stdin)
inputs=j[\"inputs\"]
def walk(x,path=\"\"):
    if isinstance(x,dict):
        if \"name\" in x and \"options\" in x:
            opts=x[\"options\"]
            if isinstance(opts,list):
                for o in opts:
                    if isinstance(o,(dict,list)):
                        continue
                    s=str(o).lower()
                    if \"hg38\" in s or (\"homo\" in s and \"sapiens\" in s):
                        print(path, x.get(\"name\"), o)
        for k,v in x.items():
            if k in (\"options\",): continue
            walk(v,path+\"/\"+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+\"/\"+str(i))
walk(inputs)
'"

